var t=[{title:`Výhody`,text:`Každá ruka nese vlastní zátěž, což usnadňuje jednostrannou práci a umožňuje úhly úchopu, které pevná tyč nemusí dovolit. Přítah nebo tlak jednou rukou může ukázat rozdíly v kontrole mezi vašimi stranami. Jednoručky se často vejdou do malých prostor lépe než plné vybavení s činkou, ačkoli skoky mezi váhami mohou být velké nebo výběr omezený.`},{title:`Zvolte váhu`,text:`Vyberte pár nebo jednu jednoručku, která vám dovolí dosáhnout cílových opakování se stabilním pohybem a několika opakováními v rezervě. Jako začátečník můžete potřebovat různé zátěže pro přítahy, zdvihy pro biceps a tlaky. Pokud je další váha příliš těžká, nejdřív s lehčí přidejte opakování, rozsah nebo kontrolu.`},{title:`Bezpečně se dostaňte do polohy`,text:`U tlaku na lavici se posaďte s jednoručkami pevně drženými u stehen, pod kontrolou se položte na záda a váhy přemístěte na místo bez házení. U cviků ve stoje zvedněte váhy nohama a trupem ve stabilní poloze. Neupouštějte váhy tam, kde by se mohly odrazit na chodidla, poškodit podlahu nebo zasáhnout někoho.`},{title:`Běžné využití`,text:`Goblet dřepy a rumunské mrtvé tahy s jednoručkami trénují dolní polovinu těla, podepřené přítahy a tlaky pokrývají horní polovinu a nošení zátěže buduje úchop a kontrolu trupu. Pokud máte jen jednu jednoručku, použijte ji pro jednostranné pohyby.`},{title:`Použití v TrainUp`,text:`V Profilu zadejte váhy jednoruček, které vlastníte. Váš plán vybírá cviky, které odpovídají vašemu vybavení, prostoru a výšce stropu. Nepředepisuje váhy, takže zátěž volíte vy. Pokud si po tréninku zapisujete zátěže, pište je pokaždé stejně, například „12 kg na ruku“.`}];var a=[{label:`Mayo Clinic: volné váhy a posilovací stroje`,url:`https://www.augustahealth.com/answer/weight-training-free-weights-vs-machine-weights/`},{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: technika posilování (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var n={sections:t,sources:a};export{n as default,t as sections,a as sources};